#include "Aevrynd/HeightField3D.h"
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <map>
using namespace Aevrynd;
#include "RiverProductionExtract.h"
double CrossXZ(Vec3 a,Vec3 b,Vec3 c){return double(b.x-a.x)*(c.z-a.z)-double(b.z-a.z)*(c.x-a.x);}
unsigned Overlaps(const Mesh3D&m){unsigned overlaps=0;const auto point=[&](unsigned i){const auto&v=m.vertices[i];return Vec3{v.x*30,0,v.z*272};};for(std::size_t a=0;a<m.indices.size();a+=3)for(std::size_t b=a+3;b<m.indices.size();b+=3){std::vector<Vec3> poly;for(unsigned j=0;j<3;++j)poly.push_back(point(m.indices[a+j]));for(unsigned edge=0;edge<3&&!poly.empty();++edge){Vec3 c=point(m.indices[b+edge]),d=point(m.indices[b+(edge+1)%3]);std::vector<Vec3> next;for(std::size_t j=0;j<poly.size();++j){Vec3 p=poly[j],q=poly[(j+1)%poly.size()];double dp=CrossXZ(c,d,p),dq=CrossXZ(c,d,q);bool insideP=dp<=0,insideQ=dq<=0;if(insideP)next.push_back(p);if(insideP!=insideQ)next.push_back(p+(q-p)*float(dp/(dp-dq)));}poly=std::move(next);}double area=0;for(std::size_t j=1;j+1<poly.size();++j)area+=std::abs(CrossXZ(poly[0],poly[j],poly[j+1]))*.5;overlaps+=area>.0001;}return overlaps;}
float Center(float z){return -4.f+std::sin(z*.035f)*5.f+std::sin(z*.011f)*2.f;}
float Width(float z){return 12.f+std::sin(z*.057f+.7f)*2.6f;}
HeightField3D Terrain(){HeightField3D t({{-256,0,-256},129,129,4});if(!t.GenerateUltra(0x4a17u,{10.5f,.0105f,.56f,.22f,24.f,.34f,7,3,.68f,.16f}))throw std::runtime_error("terrain");t.FlattenCircle({-16,0,8},8,0,8);t.FlattenCircle({-12,0,24},7.2f,0,4.5f);return t;}
void OldCarve(HeightField3D& t){for(unsigned z=0;z<129;++z)for(unsigned x=0;x<129;++x){auto p=t.SamplePosition(x,z);if(std::abs(p.z)>142)continue;const float w=Width(p.z),d=std::abs(p.x-Center(p.z)),outer=w*.5f+7;if(d>=outer)continue;const float blend=Clamp((d-w*.42f)/(outer-w*.42f),0.f,1.f),h=t.Height(x,z);t.SetHeight(x,z,(std::min)(h,-2.4f+(h+2.4f)*blend*blend*(3-2*blend)));}t.RecalculateRange();}
// 與 CreateMesh 的 a/c/b、b/c/d 對角相同，不能以雙線性高度冒充 raster 三角形。
float TriangleHeight(const HeightField3D&t,float x,float z){const auto s=t.Settings();float gx=(x-s.origin.x)/s.cellSize,gz=(z-s.origin.z)/s.cellSize;unsigned ix=unsigned(std::floor(gx)),iz=unsigned(std::floor(gz));float u=gx-ix,v=gz-iz;float a=t.Height(ix,iz),b=t.Height(ix+1,iz),c=t.Height(ix,iz+1),d=t.Height(ix+1,iz+1);return u+v<=1?a+(b-a)*u+(c-a)*v:d+(c-d)*(1-u)+(b-d)*(1-v);}
void AdaptiveCheck(const HeightField3D&t,const std::filesystem::path&root){
 const auto m=CreateShowcaseRiverRefinedTerrainMesh3D(t);std::map<std::pair<unsigned,unsigned>,unsigned> edges;
 unsigned invalid=0,interiorBoundary=0,nonmanifold=0;double area=0;float heightError=0;
 for(std::size_t i=0;i<m.indices.size();i+=3){const auto&a=m.vertices[m.indices[i]],&b=m.vertices[m.indices[i+1]],&c=m.vertices[m.indices[i+2]];const double cross=CrossXZ({a.x,a.y,a.z},{b.x,b.y,b.z},{c.x,c.y,c.z});invalid+=cross>=0;area-=cross*.5;for(unsigned j=0;j<3;++j){const unsigned a=m.indices[i+j],b=m.indices[i+(j+1)%3];++edges[{(std::min)(a,b),(std::max)(a,b)}];}}
 for(const auto&[e,n]:edges){nonmanifold+=n>2;if(n==1){const auto&a=m.vertices[e.first],&b=m.vertices[e.second];const bool outer=(a.x==-256&&b.x==-256)||(a.x==256&&b.x==256)||(a.z==-256&&b.z==-256)||(a.z==256&&b.z==256);interiorBoundary+=!outer;}}
 for(const auto&v:m.vertices)if(std::abs(v.x)<255.99f&&std::abs(v.z)<255.99f)heightError=(std::max)(heightError,std::abs(v.y-TriangleHeight(t,v.x,v.z)));
 std::ofstream out(root/"adaptive-terrain-receipt.json");out<<"{\"heightfieldSamples\":"<<t.SampleCount()<<",\"cellSize\":"<<t.Settings().cellSize<<",\"displayVertices\":"<<m.vertices.size()<<",\"displayTriangles\":"<<m.indices.size()/3<<",\"fullFineTriangles\":524288,\"interiorBoundaryEdges\":"<<interiorBoundary<<",\"nonmanifoldEdges\":"<<nonmanifold<<",\"invalidTriangles\":"<<invalid<<",\"area\":"<<area<<",\"maximumVertexTriangleHeightError\":"<<heightError<<"}";
 std::cout<<"ADAPTIVE vertices="<<m.vertices.size()<<" triangles="<<m.indices.size()/3<<" interiorBoundary="<<interiorBoundary<<" heightError="<<heightError<<'\n';
 const auto water=CreateRiverHeroCellMesh3D(t);float bilinearDifference=0;
 for(const auto&v:water.vertices){const float x=v.x*30,z=v.z*272;bilinearDifference=(std::max)(bilinearDifference,std::abs(t.SampleHeight(x,z)-TriangleHeight(t,x,z)));}
 std::ofstream collision(root/"height-query-difference.json");collision<<"{\"maximumBilinearVsTriangleAtWaterVertices\":"<<bilinearDifference<<",\"note\":\"existing SampleHeight is bilinear; raster water boundary gate uses actual triangles\"}";
 collision.close();if(bilinearDifference>.001f)throw std::runtime_error("collision query does not match raster triangles within 1mm");
 if(m.indices.size()/3>=100000||interiorBoundary||nonmanifold||invalid||std::abs(area-512.0*512.0)>.01||heightError>.001)throw std::runtime_error("adaptive terrain topology gate");
}
void NewCheck(const HeightField3D&t,const std::filesystem::path&root){if(t.Settings().cellSize>1.f)throw std::runtime_error("refinement gate: production shoreline still uses 4m terrain");const auto m=CreateRiverHeroCellMesh3D(t);std::map<std::pair<unsigned,unsigned>,unsigned> edges;float boundaryMax=0,minDepth=10000;unsigned boundary=0,nonmanifold=0;const auto p=[&](unsigned i){const auto&v=m.vertices[i];return Vec3{v.x*30,-.42f,v.z*272};};for(std::size_t i=0;i<m.indices.size();i+=3){for(unsigned j=0;j<3;++j){unsigned a=m.indices[i+j],b=m.indices[i+(j+1)%3];++edges[{(std::min)(a,b),(std::max)(a,b)}];}for(unsigned u=0;u<=8;++u)for(unsigned v=0;v<=8-u;++v){const Vec3 q=p(m.indices[i])*(float(u)/8)+p(m.indices[i+1])*(float(v)/8)+p(m.indices[i+2])*(1-float(u+v)/8);minDepth=(std::min)(minDepth,q.y-TriangleHeight(t,q.x,q.z));}}
for(const auto&[edge,count]:edges){nonmanifold+=count>2;if(count==1){++boundary;for(float f:{0.f,.5f,1.f}){Vec3 q=p(edge.first)*(1-f)+p(edge.second)*f;boundaryMax=(std::max)(boundaryMax,std::abs(q.y-TriangleHeight(t,q.x,q.z)));}}}
std::vector<unsigned> group(m.vertices.size());for(unsigned i=0;i<group.size();++i)group[i]=i;const auto find=[&](unsigned i){while(group[i]!=i)i=group[i];return i;};for(const auto&[edge,count]:edges)group[find(edge.first)]=find(edge.second);std::map<unsigned,unsigned> components;for(const auto&[edge,count]:edges)++components[find(edge.first)];std::map<unsigned,unsigned> boundaryDegree;for(const auto&[edge,count]:edges)if(count==1){++boundaryDegree[edge.first];++boundaryDegree[edge.second];}unsigned wrongDegree=0;for(const auto&[v,degree]:boundaryDegree)wrongDegree+=degree!=2;std::cout<<" components="<<components.size()<<" boundaryVertices="<<boundaryDegree.size()<<" wrongDegree="<<wrongDegree<<'\n';
const unsigned overlaps=Overlaps(m);unsigned badUvNormals=0;for(const auto&v:m.vertices)badUvNormals+=!std::isfinite(v.x)||!std::isfinite(v.z)||v.normal!=PackNormalSnorm8({0,1,0})||std::abs(v.u-v.x)>.00001f||std::abs(v.v-(v.z+.5f)*8.f)>.00001f;const auto base=Terrain();float laneDrift=0;for(unsigned j=0;j<=32;++j){const float f=float(j)/32,x=-16+4*f,z=8+16*f;laneDrift=(std::max)(laneDrift,std::abs(TriangleHeight(t,x,z)-TriangleHeight(base,x,z)));}std::cout<<" overlaps="<<overlaps<<" badUVNormals="<<badUvNormals<<" laneDrift="<<laneDrift<<'\n';
std::ofstream out(root/"new-shore-receipt.json");out<<"{\"vertices\":"<<m.vertices.size()<<",\"indices\":"<<m.indices.size()<<",\"components\":"<<components.size()<<",\"boundaryVertices\":"<<boundaryDegree.size()<<",\"boundaryEdges\":"<<boundary<<",\"maximumBoundaryDepth\":"<<boundaryMax<<",\"minimumWaterDepth\":"<<minDepth<<",\"triangleOverlapPairs\":"<<overlaps<<",\"badUvNormals\":"<<badUvNormals<<",\"safeLaneMaximumHeightDrift\":"<<laneDrift<<",\"nonmanifoldEdges\":"<<nonmanifold<<"}";out.close();std::cout<<"NEW vertices="<<m.vertices.size()<<" boundary="<<boundary<<" maxDepth="<<boundaryMax<<" minWaterDepth="<<minDepth<<'\n';if(boundaryMax>.001f||minDepth<-.001f||nonmanifold||components.size()!=1||wrongDegree||overlaps||badUvNormals||laneDrift>.05f)throw std::runtime_error("shore geometry gate");}
int main(int argc,char**argv){try{if(argc!=2)return 2;auto t=Terrain();OldCarve(t);float minDepth=10000,maxDepth=-10000;unsigned bad=0,count=0;for(unsigned i=0;i<=64;++i){float z=-136+272.f*i/64;for(float side:{-1.f,1.f}){float depth=-.42f-TriangleHeight(t,Center(z)+side*Width(z)*.5f,z);minDepth=(std::min)(minDepth,depth);maxDepth=(std::max)(maxDepth,depth);bad+=std::abs(depth)>.01f;++count;}}std::ofstream out(std::filesystem::path(argv[1])/"old-boundary-failure.json");out<<"{\"samples\":"<<count<<",\"boundaryFailuresOver1cm\":"<<bad<<",\"minimumDepth\":"<<minDepth<<",\"maximumDepth\":"<<maxDepth<<",\"method\":\"actual terrain triangles, original carve and 64-strip banks\"}";std::cout<<"OLD samples="<<count<<" failures="<<bad<<" depth="<<minDepth<<".."<<maxDepth<<'\n';if(!bad)throw std::runtime_error("old failure not reproduced");auto fixed=Terrain();CarveShowcaseRiverShore3D(fixed);AdaptiveCheck(fixed,argv[1]);NewCheck(fixed,argv[1]);return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
